# List all possible 2-position swaps
base = [9, 2, 4, 9, 7, 6, 6]

swaps = {}
for i in range(len(base)):
    for j in range(i+1, len(base)):
        new_cycle = base.copy()
        new_cycle[i], new_cycle[j] = new_cycle[j], new_cycle[i]
        key = str(new_cycle)
        if key not in swaps:
            swaps[key] = new_cycle

print(f"Total unique swaps: {len(swaps)}")
for key in sorted(swaps.keys()):
    print(f"  {key}")
